<main class="container">
<div class="page-heading"><div><h1>AI-Assisted Deposit Disputes</h1><p>Capture condition evidence, compare images locally, and record a manager-approved deposit settlement.</p></div></div>
<div class="notice"><strong>Privacy:</strong> photos are stored in your local project folder and analysed by a Python service on this computer. They are not sent to a cloud AI provider. <strong>Important:</strong> the current engine detects visual differences only; it does not prove damage, tenant responsibility, or repair cost.</div>
<?php if($error): ?><div class="notice error"><?=e($error)?></div><?php endif; ?>
<section class="panel"><h2>Create a dispute case</h2>
<?php if(!$tenancies): ?><p>No tenancy records are available under your properties yet. Register a tenant first.</p><?php else: ?>
<form method="post" action="<?=e(base_url('?page=disputes'))?>"><?=csrf_field()?><input type="hidden" name="action" value="create"><label for="tenancyId">Tenant / tenancy</label><select id="tenancyId" name="tenancyId" required><option value="">Choose a tenancy</option><?php foreach($tenancies as $tn): ?><option value="<?=(int)$tn['tenancyId']?>"><?=e($tn['fullName'].' — '.$tn['propertyName'].' / '.$tn['unitNumber'].' — Caution fee ₦'.number_format((float)$tn['cautionFee'],2).' ('.$tn['status'].')')?></option><?php endforeach; ?></select><button type="submit">Create dispute case</button></form><?php endif; ?></section>
<section class="panel"><h2>Dispute cases</h2><?php if(!$cases): ?><p>No deposit disputes have been created yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Tenant / unit</th><th>Created</th><th>Caution fee</th><th>Status</th><th>Settlement</th><th>Action</th></tr></thead><tbody><?php foreach($cases as $c): ?><tr><td><?=e($c['fullName'])?><br><?=e($c['propertyName'].' / '.$c['unitNumber'])?></td><td><?=e($c['createdAt'])?></td><td>₦<?=number_format((float)$c['cautionFee'],2)?></td><td><span class="status <?= $c['status']==='resolved'?'vacant':'occupied' ?>"><?=e(ucfirst($c['status']))?></span></td><td><?php if($c['status']==='resolved'): ?>Deduction: ₦<?=number_format((float)$c['finalDeduction'],2)?><br>Refund: ₦<?=number_format((float)$c['refundAmount'],2)?><?php else: ?>Not settled<?php endif; ?></td><td><a href="<?=e(base_url('?page=disputes&case='.(int)$c['disputeId']))?>">Open / review</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php if($selected): ?>
<section class="panel"><div class="page-heading"><div><h2>Case #<?=(int)$selected['disputeId']?> — <?=e($selected['fullName'])?></h2><p><?=e($selected['propertyName'].' / '.$selected['unitNumber'])?> · Tenancy <?=e($selected['startDate'])?> to <?=e($selected['endDate'])?> · Caution fee ₦<?=number_format((float)$selected['cautionFee'],2)?></p></div><span class="status <?= $selected['status']==='resolved'?'vacant':'occupied' ?>"><?=e(ucfirst($selected['status']))?></span></div>
<h3>1. Upload condition evidence</h3><p class="form-hint">Use photos of the same room or feature from similar camera positions and lighting. Each image must be JPG, PNG or WebP and no larger than 12 MB.</p>
<form method="post" enctype="multipart/form-data" action="<?=e(base_url('?page=disputes&case='.(int)$selectedId))?>"><?=csrf_field()?><input type="hidden" name="action" value="upload"><input type="hidden" name="disputeId" value="<?=(int)$selectedId?>"><div class="form-grid"><div><label for="phase">Evidence stage</label><select id="phase" name="phase" required><option value="move_in">Move-in condition</option><option value="move_out">Move-out condition</option></select></div><div><label for="photos">Select image(s)</label><input id="photos" type="file" name="photos[]" accept="image/jpeg,image/png,image/webp" multiple required></div></div><label for="caption">Description (optional)</label><input id="caption" name="caption" maxlength="255" placeholder="e.g. Living-room wall near window"><button type="submit">Upload evidence</button></form>
<h3>Evidence files</h3><?php if(!$evidence): ?><p>No evidence uploaded yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Stage</th><th>File</th><th>Caption</th><th>Uploaded</th><th>Preview</th></tr></thead><tbody><?php foreach($evidence as $ev): ?><tr><td><?= $ev['phase']==='move_in'?'Move-in':'Move-out' ?></td><td><?=e($ev['fileName'])?></td><td><?=e($ev['caption']??'—')?></td><td><?=e($ev['createdAt'])?></td><td><a target="_blank" rel="noopener" href="<?=e(base_url('?page=dispute_image&id='.(int)$ev['evidenceId']))?>">View image</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<h3>2. Run local image comparison</h3><p>Images are paired in upload order (first move-in with first move-out, second with second). Upload corresponding photos in the same order.</p><form method="post" action="<?=e(base_url('?page=disputes&case='.(int)$selectedId))?>"><?=csrf_field()?><input type="hidden" name="action" value="analyze"><input type="hidden" name="disputeId" value="<?=(int)$selectedId?>"><button type="submit">Run local visual comparison</button></form>
<?php if($assessments): ?><h3>3. Local computer-vision reports</h3><?php foreach($assessments as $assessment): $report=json_decode($assessment['resultJson'],true)?:[]; ?><article class="panel"><p><strong><?=e($assessment['engine'])?></strong> · <?=e($assessment['createdAt'])?></p><p>Image pairs analysed: <?= (int)($report['pairs_analysed']??0) ?></p><?php foreach(($report['reports']??[]) as $idx=>$item): $r=$item['result']??[]; ?><div class="notice"><strong>Pair <?=($idx+1)?>:</strong> <?=e($r['change_band']??'No result')?> · Changed pixels: <?=e((string)($r['changed_pixel_percent']??'—'))?>%<p><?=e($r['summary']??'')?></p></div><?php endforeach; ?><p><strong>Limitations:</strong> <?=e($report['notice']??'Manager review required.')?></p></article><?php endforeach; ?><?php else: ?><p>No local image assessment has been run for this case yet.</p><?php endif; ?>
<h3>4. Manager review and final settlement</h3><p>The AI result must not set the deduction. Inspect original evidence, invoices/estimates and any tenant response. Enter the amount you decide to deduct.</p>
<?php if($selected['status']==='resolved'): ?><p><strong>Final deduction:</strong> ₦<?=number_format((float)$selected['finalDeduction'],2)?> · <strong>Refund due:</strong> ₦<?=number_format((float)$selected['refundAmount'],2)?></p><form method="post" action="<?=e(base_url('?page=disputes&case='.(int)$selectedId))?>"><?=csrf_field()?><input type="hidden" name="action" value="reopen"><input type="hidden" name="disputeId" value="<?=(int)$selectedId?>"><button type="submit">Reopen for review</button></form><?php else: ?><form method="post" action="<?=e(base_url('?page=disputes&case='.(int)$selectedId))?>"><?=csrf_field()?><input type="hidden" name="action" value="settle"><input type="hidden" name="disputeId" value="<?=(int)$selectedId?>"><label for="finalDeduction">Final deduction (₦; maximum <?=number_format((float)$selected['cautionFee'],2)?>)</label><input id="finalDeduction" name="finalDeduction" type="number" min="0" max="<?=e((string)$selected['cautionFee'])?>" step="0.01" required><label for="managerNotes">Manager's reason / supporting basis</label><textarea id="managerNotes" name="managerNotes" rows="4" required placeholder="Explain the decision and supporting evidence or repair estimate."></textarea><button type="submit">Approve settlement and calculate refund</button></form><?php endif; ?>
</section><?php endif; ?>
</main>
